import React, { useState } from 'react'
import { Eye, EyeOff, Lock, User, ShieldCheck, AlertCircle, ArrowRight, Globe2 } from 'lucide-react'

export function LoginView({ onLogin, language, onToggleLanguage, t }) {
  const [username, setUsername] = useState('admin')
  const [password, setPassword] = useState('AdminPassword123!')
  const [showPassword, setShowPassword] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: username.trim(), password })
      })

      if (!response.ok) {
        let msg = t('login.failed') || 'Invalid username or password'
        try {
          const err = await response.json()
          msg = err.detail || err.message || msg
        } catch {}
        throw new Error(msg)
      }

      const data = await response.json()
      onLogin(data.accessToken, data.user)
    } catch (err) {
      setError(err.message || 'Login failed')
    } finally {
      setLoading(false)
    }
  }

  const fillQuick = (u, p) => {
    setUsername(u)
    setPassword(p)
    setError('')
  }

  return (
    <div className="login-page-container">
      <div className="login-card">
        {/* Header with Brand & Language Switcher */}
        <div className="login-header">
          <div className="login-brand">
            <div className="login-logo-icon">
              <ShieldCheck size={24} />
            </div>
            <div>
              <div className="login-brand-title">Mekong Identity</div>
              <div className="login-brand-subtitle">Enterprise IAM Console</div>
            </div>
          </div>

          <button
            type="button"
            className="lang-pill-btn"
            onClick={onToggleLanguage}
            title={language === 'en' ? 'ប្តូរទៅភាសាខ្មែរ' : 'Switch to English'}
          >
            <Globe2 size={13} />
            <span>{language === 'en' ? 'ខ្មែរ' : 'EN'}</span>
          </button>
        </div>

        <div className="login-welcome-text">
          <h1>{t('login.title') || 'Sign in to Console'}</h1>
          <p>{t('login.subtitle') || 'Enter your credentials to access the identity workspace'}</p>
        </div>

        {error && (
          <div className="login-error-banner">
            <AlertCircle size={16} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label>{t('profile.username') || 'Username or Email'}</label>
            <div className="input-with-icon">
              <User size={16} className="input-icon" />
              <input
                type="text"
                required
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="admin or admin@istad.co"
                autoComplete="username"
              />
            </div>
          </div>

          <div className="form-group">
            <div className="label-row">
              <label>{t('changePassword.newPassword') || 'Password'}</label>
            </div>
            <div className="input-with-icon">
              <Lock size={16} className="input-icon" />
              <input
                type={showPassword ? 'text' : 'password'}
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••••••"
                autoComplete="current-password"
              />
              <button
                type="button"
                className="password-toggle-btn"
                onClick={() => setShowPassword(!showPassword)}
                tabIndex={-1}
              >
                {showPassword ? <EyeOff size={15} /> : <Eye size={15} />}
              </button>
            </div>
          </div>

          <button type="submit" disabled={loading} className="btn-primary login-submit-btn">
            {loading ? (
              <span className="spinner-sm" />
            ) : (
              <>
                <span>{t('login.submit') || 'Sign In'}</span>
                <ArrowRight size={16} />
              </>
            )}
          </button>
        </form>

        {/* Quick Demo Credentials */}
        <div className="quick-creds-box">
          <div className="quick-creds-label">
            {language === 'km' ? 'គណនីសាកល្បងរហ័ស:' : 'Quick Demo Credentials:'}
          </div>
          <div className="quick-creds-chips">
            <button
              type="button"
              className="quick-chip"
              onClick={() => fillQuick('admin', 'AdminPassword123!')}
            >
              <span className="chip-badge admin">ADMIN</span> admin
            </button>
            <button
              type="button"
              className="quick-chip"
              onClick={() => fillQuick('user', 'UserPassword123!')}
            >
              <span className="chip-badge user">USER</span> user
            </button>
          </div>
        </div>

        {/* Social Logins */}
        <div className="login-divider">
          <span>{language === 'km' ? 'ឬចូលតាមរយៈ' : 'or continue with'}</span>
        </div>

        <div className="social-links-grid">
          <a
            href="/oauth2/authorization/google?prompt=select_account"
            className="social-auth-btn"
            onClick={() => {
              document.cookie = `iam_auth_origin=${window.location.origin}; path=/; max-age=300`
            }}
          >
            <svg width="16" height="16" viewBox="0 0 24 24"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.06H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.94l2.85-2.22.81-.63z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.52 6.16-4.52z"/></svg>
            <span>Google</span>
          </a>
          <a
            href="/oauth2/authorization/github?prompt=consent"
            className="social-auth-btn"
            onClick={() => {
              document.cookie = `iam_auth_origin=${window.location.origin}; path=/; max-age=300`
            }}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path fillRule="evenodd" clipRule="evenodd" d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.53 1.032 1.53 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z"/></svg>
            <span>GitHub</span>
          </a>
        </div>
      </div>
    </div>
  )
}
